import numpy as npimport pandas as pddef align_reference_peak(    df,    window=(-0.3, 0.3),    target_ppm=0.0,    fill_value=0.0,):    """    Align NMR spectra using a reference peak.    The maximum peak inside `window` is shifted to `target_ppm`    using integer-point shifting.    Parameters    ----------    df : pandas.DataFrame        Rows = samples and columns = ppm values.    window : tuple of float, default=(-0.3, 0.3)        Ppm region containing the reference peak.    target_ppm : float, default=0.0        Ppm position to which the reference peak is aligned.    fill_value : float, default=0.0        Value used to fill empty points at the spectrum edges.    Returns    -------    pandas.DataFrame        Aligned NMR spectra.    """    ppm = df.columns.astype(float).to_numpy()    X = df.to_numpy(dtype=float)    # Select the reference-peak region    low_ppm, high_ppm = sorted(window)    mask = (ppm >= low_ppm) & (ppm <= high_ppm)    if not mask.any():        raise ValueError(            f"No ppm values found inside the window {window}."        )    # Find the column nearest the target ppm    target_index = np.argmin(np.abs(ppm - target_ppm))    # Find the maximum peak in the window for each spectrum    window_indices = np.where(mask)[0]    peak_indices = window_indices[        np.argmax(X[:, mask], axis=1)    ]    # Calculate the required shifts    shifts = target_index - peak_indices    # Create an output array    X_aligned = np.full(        X.shape,        fill_value,        dtype=float,    )    n_points = X.shape[1]    # Shift without wrapping values to the opposite edge    for row, shift in enumerate(shifts):        shift = int(shift)        if shift == 0:            X_aligned[row] = X[row]        elif shift > 0:            X_aligned[row, shift:] = X[                row, :n_points - shift            ]        else:            shift = abs(shift)            X_aligned[row, :n_points - shift] = X[                row, shift:            ]    return pd.DataFrame(        X_aligned,        index=df.index,        columns=df.columns,    )